export const validateCourseData = () => {
  const fail = (message: string): never => {
    throw new Error(`Course data invariant failed: ${message}`)
  }
  if (topics.length !== 13) fail(`expected 13 topics, got ${topics.length}`)
  const semester7 = topics.filter((topic) => topic.semester === 7)
  const semester8 = topics.filter((topic) => topic.semester === 8)
  if (semester7.length !== 7) fail(`semester 7 has ${semester7.length} topics`)
  if (semester8.length !== 6) fail(`semester 8 has ${semester8.length} topics`)
  const hours = topics.reduce((sum, topic) => sum + topic.lectureHours, 0)
  const hours7 = semester7.reduce((sum, topic) => sum + topic.lectureHours, 0)
  const hours8 = semester8.reduce((sum, topic) => sum + topic.lectureHours, 0)
  if (hours !== 38 || hours7 !== 20 || hours8 !== 18) fail(`lecture hours are ${hours7}/${hours8}/${hours}`)
  const labs = topics.flatMap((topic) => topic.labNumbers).sort((a, b) => a - b)
  if (labs.join(',') !== Array.from({ length: 16 }, (_, index) => index + 1).join(',')) fail('labs 1–16 are not mapped exactly once')
  if (new Set(topics.map((topic) => topic.id)).size !== topics.length) fail('topic ids are not unique')
  topics.forEach((topic) => {
    if (!course.semesters.includes(topic.semester)) fail(`${topic.id} has invalid semester`)
    if (![2, 4].includes(topic.lectureHours)) fail(`${topic.id} has invalid lecture hours`)
    if (!topic.competencies.length || !topic.sourceTitle || !topic.sourceContent.length || !topic.sourceIds.length) {
      fail(`${topic.id} is missing required source fields`)
    }
    if (topic.questions.length !== 8) fail(`${topic.id} has ${topic.questions.length} questions`)
  })
  return true
}

validateCourseData()
